import{_ as o,o as d,c,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const E=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-SAVE-Command.md","filePath":"manual-zh/Matrix-SAVE-Command.md","lastUpdated":1785684581000}'),S={name:"manual-zh/Matrix-SAVE-Command.md"};function t(_,e,n,r,A,s){return d(),c("div",null,[...e[0]||(e[0]=[a(`<h4 id="_16-4-10-save-命令" tabindex="-1">16.4.10 <code>SAVE</code> 命令 <a class="header-anchor" href="#_16-4-10-save-命令" aria-label="Permalink to &quot;16.4.10 \`SAVE\` 命令&quot;">​</a></h4><pre><code>SAVE _expression_
     [/OUTFILE={_file_ _|_ *}]
     [/VARIABLES=_variable_ …]
     [/NAMES=_expression_]
     [/STRINGS=_variable_ …].
</code></pre><p><code>SAVE</code> 矩阵命令求值 <em>expression</em>，并将结果矩阵写入 SPSS 系统文件。在系统文件中，矩阵的每一行成为一个个案，每一列成为一个变量。</p><p>在 <code>OUTFILE</code> 子命令上指定 SPSS 系统文件的名称或句柄，或使用 “*” 将输出写为新的活动文件。在语法顺序中，<code>OUTFILE</code> 子命令在 <code>MATRIX</code> 内的第一个 <code>SAVE</code> 命令上是必需的。对于第一个之后的 <code>SAVE</code> 命令，默认输出文件与上一个相同。</p><p>当多个 <code>SAVE</code> 命令在单个 <code>MATRIX</code> 内写入同一目标时，后面的命令追加到同一个输出文件。写入文件的所有矩阵必须具有相同的列数。<code>VARIABLES</code>、<code>NAMES</code> 和 <code>STRINGS</code> 子命令仅对写入给定文件的第一个 <code>SAVE</code> 命令有效。</p><p>默认情况下，<code>SAVE</code> 将输出文件中的变量命名为 <code>COL1</code> 到 <code>COL _n_</code>。使用 <code>VARIABLES</code> 或 <code>NAMES</code> 为变量提供有意义的名称。<code>VARIABLES</code> 子命令接受逗号分隔的变量名列表。其替代项 <code>NAMES</code> 改为接受一个表达式，该表达式必须求值为一行或一列字符串名称向量。名称的数量不必与待写矩阵的列数精确匹配：多余的名称被忽略；多余的列使用默认名称。</p><p>默认情况下，<code>SAVE</code> 假定待写矩阵全为数值型。要写入字符串列，在 <code>STRINGS</code> 上指定字符串列的变量名的逗号分隔列表。</p>`,7)])])}const i=o(S,[["render",t]]);export{E as __pageData,i as default};
